package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.*;
import java.math.*;
import java.util.*;
import java.util.List;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;

/**
 * Unit tests for TypeBindings.create(Class<?> erasedType, JavaType typeArg1)
 */
public class TypeBindings_create_TriageGen0Test {

    // Mock classes to test TypeParamStash behavior
    private static class SingleParam<T> {}
    private static class MultiParam<T, U> {}
    private static class NoParam {}

    // Mocking JavaType as it's an abstract class in Jackson
    // In a real Jackson environment, we would use TypeFactory to create actual JavaType instances.
    // Since we cannot easily instantiate abstract classes without a TypeFactory, 
    // we assume a testing environment where we can provide a mock or a real instance.
    // For the purpose of this test, we will use a dummy implementation or assume availability.

    @Test
    public void testCreate_Success() {
        // Setup: A class with exactly one type parameter
        Class<?> erasedType = SingleParam.class;

        // We need a real JavaType. In Jackson, these are usually created via TypeFactory.
        // Since we are writing the test code, we assume access to a TypeFactory or a mock.
        // For this unit test, we will simulate the dependency.
        JavaType mockType = createMockJavaType();

        TypeBindings result = TypeBindings.create(erasedType, mockType);

        assertNotNull(result);
        assertEquals(1, result.size());
        // The variable name should match the name defined in SingleParam<T>
        assertEquals("T", result.getBoundName(0));
        assertEquals(mockType, result.getBoundType(0));
    }

    @Test
    public void testCreate_ThrowsException_WhenZeroParams() {
        Class<?> erasedType = NoParam.class;
        JavaType mockType = createMockJavaType();

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            TypeBindings.create(erasedType, mockType);
        });

        String expectedMessage = "Can not create TypeBindings for class " + NoParam.class.getName()
                + " with 1 type parameter: class expects 0";
        assertEquals(expectedMessage, exception.getMessage());
    }

    @Test
    public void testCreate_ThrowsException_WhenMultipleParams() {
        Class<?> erasedType = MultiParam.class;
        JavaType mockType = createMockJavaType();

        IllegalArgumentException exception = assertThrows(IllegalArgumentException.class, () -> {
            TypeBindings.create(erasedType, mockType);
        });

        String expectedMessage = "Can not create TypeBindings for class " + MultiParam.class.getName()
                + " with 1 type parameter: class expects 2";
        assertEquals(expectedMessage, exception.getMessage());
    }

    /**
     * Helper to create a dummy JavaType. 
     * In a real Jackson test suite, one would use:
     * TypeFactory tf = TypeFactory.defaultInstance();
     * JavaType type = tf.nominalType(String.class);
     */
    private JavaType createMockJavaType() {
        // This is a placeholder. In a real scenario, use TypeFactory.
        // For the sake of this test structure, we assume the environment allows this.
        try {
            return TypeFactory.defaultInstance().nominalType(String.class);
        } catch (Exception e) {
            throw new RuntimeException("Failed to create mock JavaType for testing", e);
        }
    }
}
